UML Generator.class_diagram:
classDiagram
    class User {
        +id
        +name
        +email
    }
    class Student {
        +takeExam()
        +viewResult()
    }
    class Teacher {
        +createQuestion()
        +scheduleExam()
        +reviewResult()
    }
    class Admin {
        +manageUser()
        +configureSettings()
    }
    class Exam {
        +startTime
        +duration
        +grade()
    }
    class Question {
        +text
        +type
        +score
    }
    User <|-- Student
    User <|-- Teacher
    User <|-- Admin
    Exam "1" *-- "*" Question
    Student "*" --> "1" Exam
    Teacher "*" --> "*" Question
    Teacher "*" --> "*" Exam

